    && typeof v.uploadSha256==='string' && HASH.test(v.uploadSha256)
    && typeof v.fileUploadId === 'string' && v.fileUploadId.length > 0 && typeof v.storageRef === 'string'
    && typeof v.uploadStoragePath === 'string' && (v.programId === null || (typeof v.programId === 'string' && UUID.test(v.programId)))
    && (v.workspaceId === null || positiveId(v.workspaceId)) && Number.isSafeInteger(v.sizeBytes) && v.sizeBytes >= 0
    && typeof v.fileName === 'string' && typeof v.mimeType === 'string' && object(v.lineage)
