  if (!Object.hasOwn(metadata, 'dataRoomProcessing')) return null;
  const s = metadata.dataRoomProcessing;
  const valid = object(s) && s.version === DATA_ROOM_PROCESSING_SCHEMA_VERSION && s.stage === DATA_ROOM_PROCESSING_STAGE
    && s.processorRevision === DATA_ROOM_PROCESSOR_REVISION && ['running','completed','failed','blocked'].includes(s.state)
    && validIdentity(s.identity) && typeof s.attemptId === 'string' && UUID.test(s.attemptId)
    && Number.isSafeInteger(s.attempts) && s.attempts>0 && validTimestamp(s.claimedAt) && nullableTime(s.leaseExpiresAt)
    && nullableTime(s.nextRetryAt) && nullableTime(s.completedAt) && typeof s.retryable === 'boolean'
    && (s.reasonCode === null || DATA_ROOM_PROCESSING_REASON_CODES.includes(s.reasonCode))
    && (s.state === 'running' ? validTimestamp(s.leaseExpiresAt) && s.completedAt === null && s.nextRetryAt === null
      && !s.retryable && s.reasonCode===null && Date.parse(s.leaseExpiresAt)>Date.parse(s.claimedAt)
      && Date.parse(s.leaseExpiresAt)-Date.parse(s.claimedAt)<=PROCESSING_LEASE_MS
      : s.leaseExpiresAt === null)
    && (s.state === 'completed' ? validTimestamp(s.completedAt) && Date.parse(s.completedAt)>=Date.parse(s.claimedAt)
      && !s.retryable && s.reasonCode === null && s.nextRetryAt === null : s.completedAt === null)
    && (s.state==='blocked' ? !s.retryable && s.reasonCode!==null : true)
    && (s.state === 'failed' && s.retryable ? validTimestamp(s.nextRetryAt) : s.nextRetryAt === null);
