  if (!HASH.test(row.checksum ?? '') || !HASH.test(upload.checksum_sha256 ?? '') || row.checksum !== upload.checksum_sha256
    || typeof fileUploadId !== 'string' || !fileUploadId || typeof row.stored_artifact_ref !== 'string'
    || row.stored_artifact_ref !== upload.storage_path || !upload.storage_path.startsWith(prefix)
    || path.posix.normalize(upload.storage_path) !== upload.storage_path || /(^|\/)\.{1,2}(\/|$)/.test(upload.storage_path)
    || upload.storage_path.endsWith('/') || sizeBytes === null) throw new ProcessingRefusal('blocked','ORIGINAL_IDENTITY_INVALID');
  return {
    organizationId:Number(row.organization_id), sourceId:Number(row.id), sha256:row.checksum, fileUploadId,
    storageRef:row.stored_artifact_ref, programId:row.client_program_id ?? null, workspaceId:row.client_workspace_id ?? null,
    uploadSha256:upload.checksum_sha256, uploadStoragePath:upload.storage_path, sizeBytes,
    fileName:upload.original_name ?? row.title ?? '', mimeType:upload.mime_type ?? 'application/octet-stream', lineage:lineage(row.provenance),
    sourceTitle:row.title??null,uploadFileName:upload.original_name??null,
